class HttpClient{public static $responses=[],$requests=[];public static function get($url,$headers=[]){self::$requests[]=$url;return ['status'=>200,'body'=>json_encode(array_shift(self::$responses))];}public static function put($url,$body,$headers=[]){self::$requests[]=['url'=>$url,'body'=>json_decode($body,true)];return ['status'=>200,'body'=>''];}public static function delete($url,$headers=[]){self::$requests[]=['method'=>'DELETE','url'=>$url];return ['status'=>200,'body'=>''];}public static function post($url,$body,$headers=[]){self::$requests[]=json_decode($body,true);return ['status'=>200,'body'=>json_encode(['Response'=>array_shift(self::$responses)])];}}
